// ===================== PARSE SSH SNAPSHOT =====================
const snapshot = $('SSH: System Snapshot').item.json.stdout || '';
const sections = {};
let cur = 'unknown';
snapshot.split('\n').forEach(line => {
  if (line.startsWith('SECTION:')) { cur = line.substring(8).trim(); sections[cur] = []; }
  else { sections[cur] = sections[cur] || []; sections[cur].push(line); }
});

const containerOutput = (sections.containers || []).join('\n');
const nfsOk = (sections.nfs || ['fail'])[0].trim() === 'ok';
const stateStr = (sections.state || ['{}']).join('\n').trim();
let state;
try { state = JSON.parse(stateStr); } catch(e) { state = {}; }
if (!state.incidents) state.incidents = {};
if (!state.proxmox) state.proxmox = { vm100_retries: 0, status: 'ok' };
if (!state.nfs_info) state.nfs_info = { retries: 0, status: 'ok' };

// Parse container statuses
const containerStatus = {};
containerOutput.split('\n').filter(l => l.trim()).forEach(line => {
  const parts = line.split('\t');
  if (parts.length >= 2) containerStatus[parts[0].trim()] = parts.slice(1).join('\t').trim();
});

function isUp(name) {
  const s = containerStatus[name] || '';
  return s.toLowerCase().startsWith('up') && !s.toLowerCase().includes('unhealthy');
}

// ===================== HTTP CHECK RESULTS =====================
function httpOk(nodeName) {
  try {
    const out = $(nodeName).item.json;
    if (out.error || out.code === 'ECONNREFUSED' || out.code === 'ETIMEDOUT') return false;
    const sc = out.statusCode || out.status;
    if (sc && sc >= 500) return false;
    return true;
  } catch(e) { return false; }
}

const nasOk = httpOk('HTTP: Check NAS');
const internetOk = httpOk('HTTP: Check Internet');
const routerOk = httpOk('HTTP: Check Router');
const npmHttpOk = httpOk('HTTP: Check NPM');
const piholeHttpOk = httpOk('HTTP: Check Pi-hole');
const n8nHttpOk = httpOk('HTTP: Check n8n');

let vm100Running = true; // Assume ok if we can't check
try {
  const authOut = $('HTTP: Auth Proxmox').item.json;
  const proxmoxApiOk = !authOut.error && !!authOut.data?.ticket;
  if (proxmoxApiOk) {
    const vm100Out = $('HTTP: Check VM 100').item.json;
    const st = vm100Out?.data?.status || vm100Out?.data?.qmpstatus || '';
    vm100Running = st === 'running';
  }
} catch(e) {}

// ===================== SERVICE DEFINITIONS =====================
const services = [
  {name:'npm-app-1', tier:'critical', max:2, path:'/home/beanz/homelab/docker/infrastructure/nginx-proxy-manager', extra:npmHttpOk},
  {name:'pihole', tier:'critical', max:2, path:'/home/beanz/homelab/docker/infrastructure/pihole', extra:piholeHttpOk},
  {name:'cloudflared-tunnel', tier:'critical', max:2, path:'/home/beanz/homelab/docker/infrastructure/cloudflared', extra:true},
  {name:'n8n', tier:'critical', max:2, path:'/home/beanz/homelab/docker/automation/n8n', extra:n8nHttpOk},
  {name:'homeassistant', tier:'important', max:3, path:'/home/beanz/homelab/docker/smart-home/homeassistant', extra:true},
  {name:'nextcloud-app', tier:'important', max:3, path:'/home/beanz/homelab/docker/productivity/nextcloud', extra:true},
  {name:'immich-immich-server-1', tier:'important', max:3, path:'/home/beanz/homelab/docker/productivity/immich', extra:true},
  {name:'portainer', tier:'important', max:3, path:'/home/beanz/homelab/docker/infrastructure/portainer', extra:true},
  {name:'vaultwarden', tier:'important', max:3, path:'/home/beanz/homelab/docker/productivity/vaultwarden', extra:true},
  {name:'mosquitto', tier:'important', max:3, path:'/home/beanz/homelab/docker/smart-home/mosquitto', extra:true},
  {name:'plex', tier:'best-effort', max:1, path:'/home/beanz/homelab/docker/media/plex', extra:true},
  {name:'jellyfin', tier:'best-effort', max:1, path:'/home/beanz/homelab/docker/media/jellyfin', extra:true},
  {name:'sonarr', tier:'best-effort', max:1, path:'/home/beanz/homelab/docker/media/sonarr', extra:true},
  {name:'radarr', tier:'best-effort', max:1, path:'/home/beanz/homelab/docker/media/radarr', extra:true},
  {name:'prowlarr', tier:'best-effort', max:1, path:'/home/beanz/homelab/docker/media/prowlarr', extra:true},
  {name:'qbittorrent', tier:'best-effort', max:1, path:'/home/beanz/homelab/docker/media/qbittorrent', extra:true},
  {name:'paperless-web', tier:'best-effort', max:1, path:'/home/beanz/homelab/docker/productivity/paperless-ngx', extra:true},
  {name:'readarr', tier:'best-effort', max:1, path:'/home/beanz/homelab/docker/media/readarr', extra:true},
];

const now = new Date().toISOString();
const dockerActions = [], proxmoxActions = [], escalations = [], recoveries = [];

// ===================== EVALUATE CONTAINERS =====================
for (const svc of services) {
  const up = isUp(svc.name) && svc.extra;
  const inc = state.incidents[svc.name];
  if (up) {
    if (inc?.status === 'remediating') { recoveries.push({name:svc.name, tier:svc.tier}); delete state.incidents[svc.name]; }
    else if (inc?.status === 'awaiting_user' && Date.now() - new Date(inc.firstSeen).getTime() > 86400000) delete state.incidents[svc.name];
    continue;
  }
  if (!inc) {
    state.incidents[svc.name] = {retries:0, firstSeen:now, lastAttempt:now, status:'remediating'};
    dockerActions.push({type:'restart', name:svc.name, tier:svc.tier, composePath:svc.path, retryNum:1});
  } else if (inc.status === 'awaiting_user') {
    // skip — already escalated
  } else if (inc.retries < svc.max) {
    inc.retries++; inc.lastAttempt = now;
    const actionType = inc.retries >= 2 ? 'pull_recreate' : 'restart';
    dockerActions.push({type:actionType, name:svc.name, tier:svc.tier, composePath:svc.path, retryNum:inc.retries+1});
  } else {
    inc.status = 'awaiting_user'; inc.lastAttempt = now;
    escalations.push({name:svc.name, tier:svc.tier, composePath:svc.path, retries:inc.retries, firstSeen:inc.firstSeen});
  }
}

// ===================== EVALUATE NFS =====================
if (nfsOk) {
  if (state.nfs_info?.status === 'remediating') recoveries.push({name:'NFS /mnt/nas', tier:'critical'});
  state.nfs_info = {retries:0, status:'ok'};
} else if (state.nfs_info?.status !== 'awaiting_user') {
  const r = state.nfs_info?.retries || 0;
  if (r < 2) {
    state.nfs_info = {retries:r+1, status:'remediating'};
    dockerActions.push({type:'nfs_remount', name:'NFS /mnt/nas', tier:'critical', composePath:null, retryNum:r+1});
  } else {
    state.nfs_info = {retries:r, status:'awaiting_user'};
    escalations.push({name:'NFS /mnt/nas', tier:'critical', composePath:null, retries:r, firstSeen:now});
  }
}

// ===================== EVALUATE PROXMOX VM 100 =====================
if (vm100Running) {
  if (state.proxmox?.status === 'remediating') recoveries.push({name:'Proxmox VM 100', tier:'critical'});
  state.proxmox = {vm100_retries:0, status:'ok'};
} else if (state.proxmox?.status !== 'awaiting_user') {
  const r = state.proxmox?.vm100_retries || 0;
  if (r < 2) {
    state.proxmox = {vm100_retries:r+1, status:'remediating'};
    proxmoxActions.push({type:'start_vm', name:'VM 100 (main-ubuntu-desktop)', retryNum:r+1});
  } else {
    state.proxmox = {vm100_retries:r, status:'awaiting_user'};
    escalations.push({name:'Proxmox VM 100 stopped', tier:'critical', composePath:null, retries:r, firstSeen:now});
  }
}

// ===================== EVALUATE NETWORK =====================
if (!internetOk && !state.incidents['_network']) {
  const msg = routerOk ? 'ISP outage: internet down, router up' : 'Network outage: router + internet both unreachable';
  state.incidents['_network'] = {retries:0, firstSeen:now, status:'awaiting_user'};
  escalations.push({name:msg, tier:'critical', composePath:null, retries:0, firstSeen:now});
} else if (internetOk && state.incidents['_network']) {
  recoveries.push({name:'Internet connectivity', tier:'critical'});
  delete state.incidents['_network'];
}

// ===================== EVALUATE NAS HTTP =====================
if (!nasOk && !state.incidents['_nas']) {
  state.incidents['_nas'] = {retries:0, firstSeen:now, status:'awaiting_user'};
  escalations.push({name:'QNAP NAS unreachable (HTTP)', tier:'critical', composePath:null, retries:0, firstSeen:now});
} else if (nasOk && state.incidents['_nas']) {
  recoveries.push({name:'QNAP NAS', tier:'critical'});
  delete state.incidents['_nas'];
}

// ===================== ENCODE STATE FOR WRITING =====================
const newStateB64 = Buffer.from(JSON.stringify(state)).toString('base64');

return [{ json: { dockerActions, proxmoxActions, escalations, recoveries, newStateB64, summary:`Docker:${dockerActions.length} Proxmox:${proxmoxActions.length} Escalations:${escalations.length} Recoveries:${recoveries.length}` } }];

const actions = $('Code: Evaluate Health Data').item.json.dockerActions;
const cmds = actions.map(a => {
  if (a.type === 'restart') return `echo RESTART:${a.name}; docker compose -f ${a.composePath}/compose.yml restart 2>&1 | tail -3 || echo FAILED:${a.name}`;
  if (a.type === 'pull_recreate') return `echo RECREATE:${a.name}; docker compose -f ${a.composePath}/compose.yml pull 2>&1 | tail -2 && docker compose -f ${a.composePath}/compose.yml up -d 2>&1 | tail -2 || echo FAILED:${a.name}`;
  if (a.type === 'nfs_remount') return 'echo NFS_REMOUNT; sudo mount -a 2>&1 || echo NFS_FAILED';
  return null;
}).filter(Boolean);
return [{ json: { script: cmds.join('\n') || 'echo no_actions' } }];
